function journalString($value): string {return is_string($value) ? $value : '';}
function journalUrl(array $post): string {return './blog?article='.rawurlencode((string)$post['slug']);}
function journalVideoId(array $post): string { $id=journalString($post['youtube_id']??''); return preg_match('/^[a-zA-Z0-9_-]{11}$/D',$id) ? $id : (blogYoutubeId(journalString($post['youtube']??''))??''); }
function journalSafeImage($value): string {
    if(!is_string($value))return '';
    if(preg_match('~^\./assets/(?:[a-zA-Z0-9_-]+/)*[a-zA-Z0-9_.-]+\.(?:png|jpg|jpeg|webp|avif)$~iD',$value))return $value;
    $url=parse_url($value);
    return $url && strtolower($url['scheme']??'')==='https' && !empty($url['host']) && empty($url['user']) && empty($url['pass']) ? $value : '';
}
function journalImage(array $post): string {
    $image=journalSafeImage($post['image']??''); if($image!=='')return $image;
    $video=journalVideoId($post); return $video!=='' ? 'https://i.ytimg.com/vi/'.$video.'/hqdefault.jpg' : './assets/blog/QCyBxcZtSH2AT8GExbe3Qe3WqA.png';
}
function journalType(array $post): string {return ['article'=>'Article','image'=>'Photo story','video'=>'Video','short'=>'Short'][$post['type']??'article']??'Article';}
function journalDate(array $post): string {$stamp=strtotime((string)($post['published_at']??''));return $stamp!==false ? date('M j, Y',$stamp) : '';}
function journalReadTime(array $post): int {return max(1,(int)ceil(str_word_count((string)($post['content']??''))/200));}
function journalCard(array $post): void { ?>
